@app.post("/webhook")
def webhook():
    payload = request.data
    sig = request.headers["Stripe-Signature"]
    event = stripe.Webhook.construct_event(payload, sig, endpoint_secret)
    if event["type"] == "payment_intent.succeeded":
        fulfil(event["data"]["object"])
